const state={workspaceKnown:false,catalogLoaded:false,catalogHasMore:false,catalogCursor:null,catalogCursors:new Set(),workspace:'library',templates:[],selected:null,draft:null,values:new Map(),dirty:false,dirtyKeys:new Set(),busy:false,tab:'fields',view:'discover',scope:'all',category:'all',page:0,pageSize:9,pending:null,loaded:false,editorId:null,bridge:'connecting',capabilities:{},cache:new Map(),templateSessions:new Map(),received:false,recentDrafts:[],fillPending:null,fillTimer:null,fillMode:'missing',revisionNote:'',copyReady:null,copyReview:null,restoreKey:null,dataAction:null,exportText:'',verifyExternal:false,externalCheck:0,externalReading:false,lastVerifiedExternal:'',dataEpoch:0};
