function clearError(){$('error-banner').hidden=true}
function setTheme(context){if(context&&['light','dark'].includes(context.theme))document.documentElement.dataset.theme=context.theme}
function unwrap(result){if(!result||typeof result!=='object')throw new Error('The library returned an empty response.');if(result.isError){const text=Array.isArray(result.content)?result.content.filter(function(x){return x.type==='text'}).map(function(x){return x.text}).join('\n'):'';throw new Error(text||'The library could not complete that action.')}if(result.structuredContent&&typeof result.structuredContent==='object')return result.structuredContent;if(result.templates||result.template||result.draft||result.selectedTemplate||result.deleted||((result.kind==='templates'||result.kind==='drafts')&&Array.isArray(result.records)))return result;if(Array.isArray(result.content)){for(const part of result.content){if(part.type==='text'){try{const parsed=JSON.parse(part.text);if(parsed&&typeof parsed==='object')return parsed}catch(_){}}}}throw new Error('The library response did not contain usable data.')}
function validSummary(t){return t&&typeof t.id==='string'&&typeof t.title==='string'&&typeof t.description==='string'&&typeof t.category==='string'&&typeof t.sample==='boolean'}
function validTemplate(t){return t&&typeof t.id==='string'&&typeof t.title==='string'&&typeof t.body==='string'&&Array.isArray(t.fields)}
async function callTool(name,args){if(!state.workspaceKnown)throw new Error('Wait for the host to identify this app workspace before using library tools.');const epoch=state.dataEpoch,workspace=state.workspace;args=Object.assign({},args,{workspace:workspace});await bridgeReady;let result;if(state.bridge==='standard'){result=await rpc('tools/call',{name:name,arguments:args})}else if(state.bridge==='openai'&&window.openai&&typeof window.openai.callTool==='function'){result=await Promise.race([window.openai.callTool(name,args),new Promise(function(_,reject){setTimeout(function(){reject(new Error('The host did not respond in time. Reopen the library to check before trying again.'))},25000)})])}else throw new Error('Open Prompt Library from ChatGPT to use your saved templates.');if(workspace!==state.workspace)throw new Error('The workspace changed while this request was running. Its result was discarded.');if(epoch!==state.dataEpoch)throw new Error('The library data was deleted while this request was running. Its result was discarded.');const data=unwrap(result);if((data.workspace||'library')!==workspace)throw new Error('The response belongs to a different workspace. It was discarded.');return data}
