function validDeletionResult(data){return !!data.deleted&&Number.isInteger(data.deleted.templates)&&data.deleted.templates>=0&&Number.isInteger(data.deleted.drafts)&&data.deleted.drafts>=0&&Array.isArray(data.templates)&&data.templates.every(function(t){return validSummary(t)&&t.sample===true})&&Array.isArray(data.recentDrafts)&&data.recentDrafts.length===0&&typeof data.deletionScope==='string'}
